import React, { useContext } from 'react';

import PatchCheckFill from '@pohodnik/icons/svg/Badges/PatchCheckFill';
import PatchExclamationFill from '@pohodnik/icons/svg/Badges/PatchExclamationFill';
import ChatFill from '@pohodnik/icons/svg/Communication/ChatFill';
import Toggles from '@pohodnik/icons/svg/Controls/Toggles';
import PencilSquare from '@pohodnik/icons/svg/Tools/PencilSquare';
import Trash from '@pohodnik/icons/svg/UI/Trash';

import { getHikingAccessGroupAsync } from '@apps/Hiking/@services/hikingRules.service';
import PageLoader from '@components/PageLoader';
import { open } from '@helpers/navigationHelper';
import notificationHelper, { error, success } from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohAva from '@ui-kit/Ava';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohCheckbox from '@ui-kit/Checkbox';
import PohDropdown from '@ui-kit/Dropdown';
import PohContainer from '@ui-kit/layout/Container';
import PohList from '@ui-kit/List';

import FAKCard from './FAKCard';
import styles from './styles.module.less';
import { AuthContext } from '../../../../contexts/AuthContext';
import {
  IFirstAidKitApprove,
  IFirstAidKitSMedicament,
} from '../../../Medicaments/@types/firstAidKit.types';
import {
  addFirstAidKitMedicamentAsync,
  deleteFirstAidKidApproversForHikingAsync,
  deleteFirstAidKitMedicamentAsync,
  editFirstAidKitMedicamentAsync,
  getFirstAidKidApproversForHikingAsync,
  getFirstAidKidForHikingAsync,
  setFirstAidKidApproversForHikingAsync,
} from '../../../Medicaments/services/firstAidKit.services';
import { getHikingDataAsync, getHikingMembersAllergies } from '../../@services/hiking.service';
import { HikingAccessGroup, HikingPosition } from '../../@types/hiking.rules';
import { IHikingData, IHikingMemberAllergy } from '../../@types/hiking.types';
import {
  addFirstAidKitMedicamentModalAsync,
  editFirstAidKitMedicamentModalAsync,
} from '../FirstAidKitAddMedicamentModal/modalHelper';

interface IFirstAidKitPageProps {
  id_hiking: number;
}

const FirstAidKitPage: React.FC<IFirstAidKitPageProps> = ({ id_hiking }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);
  const [data, setData] = React.useState<IFirstAidKitSMedicament[]>([]);
  const [err, setErr] = React.useState<string | undefined>(undefined);
  const [canEdit, setCanEdit] = React.useState(true);
  const [isTable, setIsTable] = React.useState(true);
  const [showDeadline, setShowDeadline] = React.useState(true);

  const [approves, setApproves] = React.useState<IFirstAidKitApprove[]>([]);
  const [allergies, setAllergies] = React.useState<IHikingMemberAllergy[]>([]);

  const authContext = useContext(AuthContext);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);
        const hData = await getHikingDataAsync(id_hiking);
        setHikingData(hData);

        const list = await getFirstAidKidForHikingAsync(id_hiking);
        setData(list);

        const accessGroup = await getHikingAccessGroupAsync(id_hiking);
        setCanEdit(
          [
            HikingAccessGroup.Full,
            HikingAccessGroup.All,
            HikingAccessGroup.Boss,
            HikingAccessGroup.Health,
          ].includes(accessGroup),
        );

        getFirstAidKidApproversForHikingAsync(id_hiking).then(setApproves);

        const allergiesRes = await getHikingMembersAllergies(id_hiking);
        setAllergies(allergiesRes);
      } catch (e) {
        setErr((e as Error).message);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, [id_hiking]);

  const handleAdd = () => {
    addFirstAidKitMedicamentModalAsync(id_hiking).then(async (selected) => {
      try {
        const id = await addFirstAidKitMedicamentAsync(+id_hiking, selected);

        setData((d) => [...d, { id, ...selected }]);
        notificationHelper.success('Успешно добавлено');
      } catch (e) {
        notificationHelper.error((e as Error).message);
      }
    });
  };

  const handleEdit = (m: IFirstAidKitSMedicament) => {
    editFirstAidKitMedicamentModalAsync(m, id_hiking).then(async (edited) => {
      try {
        await editFirstAidKitMedicamentAsync(+id_hiking, edited);
        setData((d) => d.map((s) => (s.id === edited.id ? edited : s)));
        notificationHelper.success('Успешно изменено');
      } catch (e) {
        notificationHelper.error((e as Error).message);
      }
    });
  };

  const handleDelete = async (m: IFirstAidKitSMedicament) => {
    if (!confirm(`Удалить ${m.medicament.name} из аптечки?`)) {
      return;
    }
    try {
      await deleteFirstAidKitMedicamentAsync(+id_hiking, m.id);
      setData((d) => d.filter((s) => s.id !== m.id));
      notificationHelper.success('Успешно удалено');
    } catch (e) {
      notificationHelper.error((e as Error).message);
    }
  };

  if (isLoading) {
    return <PageLoader />;
  }

  if (err || !hikingData) {
    return <PohAlert>{err}</PohAlert>;
  }

  const groupsMappedData: Record<string, IFirstAidKitSMedicament[]> = {};

  data.forEach((m) => {
    const k = m.medicament.category?.name || 'Без категории';
    if (!groupsMappedData[k]) {
      groupsMappedData[k] = [];
    }
    groupsMappedData[k].push(m);
  });

  return (
    <div>
      <Breadcrumb
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name },
          { href: `/hiking/${id_hiking}/fak`, text: 'Групповая аптечка', active: true },
        ]}
      />
      <PohContainer>
        <header className="d-flex justify-content-between align-items-center d-print-none">
          <h3 className="mb-3" onClick={() => setIsTable((c) => !c)}>
            Аптечка похода «{hikingData.name}»
          </h3>

          <aside className="d-flex">
            <PohButton
              size={ButtonSize.Small}
              variant={ButtonVariant.Link}
              onClick={() => open(`/hiking/${id_hiking}/comments#${HikingPosition.Medic}`)}
            >
              <ChatFill />
              &nbsp;Обсудить
            </PohButton>
            &nbsp;&nbsp;
            {canEdit && (
              <PohButton
                size={ButtonSize.Small}
                variant={ButtonVariant.Success}
                onClick={handleAdd}
              >
                Добавить
              </PohButton>
            )}
            <PohDropdown
              menu={
                <PohList
                  data={[
                    {
                      key: '1',
                      content: (
                        <PohCheckbox
                          className="text-nowrap"
                          onChange={setShowDeadline}
                          checked={showDeadline}
                          label={<span className="text-nowrap">Показывать срок годности</span>}
                        />
                      ),
                    },
                  ]}
                ></PohList>
              }
            >
              <PohButton icon={true}>
                <Toggles />
              </PohButton>
            </PohDropdown>
          </aside>
        </header>

        {isTable &&
          Object.entries(groupsMappedData).map(([groupName, list]) => {
            return (
              <section key={groupName} className={styles.breakPage}>
                <h4 className="mt-3">{groupName}</h4>
                <table className="table table-sm table-striped table-condensed table-bordered">
                  <thead>
                    <tr>
                      <th>Название</th>
                      <th>Кол‑во</th>
                      <th>Дозировка</th>
                      <th>Применение</th>
                      <th>Противопоказания</th>
                      {canEdit && <th className="d-print-none">&nbsp;</th>}
                    </tr>
                  </thead>
                  <tbody>
                    {list.map((m) => {
                      const curAllergy = allergies.filter(
                        (a) => a.id_medicament === m.medicament.id,
                      );
                      return (
                        <tr key={m.id}>
                          <td>
                            <strong>{m.medicament.name}</strong>&nbsp;
                            {m.comment.length > 0 && (
                              <em className="d-block">
                                <small>{m.comment}</small>
                              </em>
                            )}
                            {m.assignee && (
                              <small className="text-info d-block">
                                {['отв.', m.assignee.name, m.assignee.surname].join(' ')}
                              </small>
                            )}
                            {m.count_for_each > 0 && (
                              <small className="text-danger d-block">
                                +{m.count_for_each}
                                <sup>
                                  {m.medicament.form?.name.substr(0, 3).toLocaleLowerCase()}
                                </sup>{' '}
                                у каждого
                              </small>
                            )}
                          </td>
                          <td>
                            {m.amount}{' '}
                            <small>
                              {m.medicament.form?.name.substr(0, 3).toLocaleLowerCase()}
                            </small>
                            {showDeadline && (
                              <small className="d-block">
                                <small>
                                  {m.deadline ? new Date(m.deadline).toLocaleDateString() : '-'}
                                </small>
                              </small>
                            )}
                          </td>
                          <td>
                            <small>{m.medicament.dosage}</small>
                          </td>
                          <td>
                            <small>{m.medicament.usages}</small>
                          </td>
                          <td>
                            <small>{m.medicament.contraindications}</small>
                            {curAllergy.length > 0 && (
                              <PohAlert className="p-1" variant={AlertVariant.Danger}>
                                ‼️ Внимание, Аллергия!{' '}
                                {curAllergy.map((a) => {
                                  return (
                                    <li key={a.id} title={JSON.stringify(a, null, '  ')}>
                                      <strong>
                                        {[a.user.name, a.user.surname].join(' ')}
                                        {` `}
                                        <small className="text-danger">
                                          <em>{a.comment}</em>
                                        </small>
                                      </strong>
                                    </li>
                                  );
                                })}
                              </PohAlert>
                            )}
                          </td>
                          {canEdit && (
                            <td align="right" className="d-print-none">
                              <PohButton
                                icon={true}
                                onClick={() => handleEdit(m)}
                                variant={ButtonVariant.Light}
                                size={ButtonSize.Small}
                              >
                                <PencilSquare />
                              </PohButton>
                              <PohButton
                                icon={true}
                                onClick={() => handleDelete(m)}
                                variant={ButtonVariant.Light}
                                size={ButtonSize.Small}
                              >
                                <Trash />
                              </PohButton>
                            </td>
                          )}
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </section>
            );
          })}
        {!isTable && (
          <section>
            {Object.entries(groupsMappedData).map(([groupName, list]) => {
              return (
                <React.Fragment key={groupName}>
                  <h5>{groupName}</h5>

                  <div className="d-flex">
                    {list.map((m) => (
                      <FAKCard m={m} key={m.id} />
                    ))}
                  </div>
                </React.Fragment>
              );
            })}
          </section>
        )}
        <PohList
          data={hikingData.hikers
            .filter((h) =>
              h.positions.find((p) =>
                [HikingPosition.Medic, HikingPosition.Rukovidotel].includes(p.id as HikingPosition),
              ),
            )
            .map((hiker) => {
              const approve = approves.find((a) => a.user.id === hiker.idUser);
              return {
                key: hiker.idUser,
                content: (
                  <div className="d-flex align-items-center my-n1 mx-n2">
                    <PohAva src={hiker.photo['50']} alt={[hiker.name, hiker.surname].join(' ')} />
                    <div className="mx-2" style={{ width: 200 }}>
                      {[hiker.name, hiker.surname].join(' ')}
                      <small className="d-block mt-n1">
                        {hiker.positions
                          .filter((p) =>
                            [HikingPosition.Medic, HikingPosition.Rukovidotel].includes(
                              p.id as HikingPosition,
                            ),
                          )
                          .map((p) => p.name)
                          .join(', ')}
                      </small>
                    </div>
                    <div className={approve ? 'text-success' : 'text-warning'}>
                      {approve ? <PatchCheckFill /> : <PatchExclamationFill />}
                      &nbsp;&nbsp;
                      {approve
                        ? `Утверждено ${approve.date.toLocaleString().replace(',', ' в')}`
                        : 'Ожидает утверждения'}
                    </div>
                    {authContext.user && +authContext.user.id === hiker.idUser ? (
                      <PohButton
                        className="ms-auto d-print-none"
                        size={ButtonSize.Small}
                        variant={approve ? ButtonVariant.Light : ButtonVariant.Success}
                        disabled={hikingData?.start < new Date()}
                        onClick={async () => {
                          if (approve) {
                            if (!confirm('Отменить утверждение?')) return;
                            if (hikingData?.start < new Date()) {
                              alert('Нельзя после старта похода');
                              return;
                            }
                            try {
                              await deleteFirstAidKidApproversForHikingAsync(id_hiking, approve.id);
                              setApproves((ap) => ap.filter((a) => a.id != approve.id));
                              success('Отменено');
                            } catch (e) {
                              error(e);
                            }
                          } else {
                            if (!confirm('Со всем согласны?')) return;
                            try {
                              const pos = hiker.positions.filter((p) =>
                                [HikingPosition.Medic, HikingPosition.Rukovidotel].includes(
                                  p.id as HikingPosition,
                                ),
                              );
                              const tasks = pos.map((p) =>
                                setFirstAidKidApproversForHikingAsync(id_hiking, p.id),
                              );
                              const resIds = await Promise.all(tasks);
                              setApproves((ap) =>
                                ap.concat(
                                  ...resIds.map((id, i) => {
                                    return {
                                      id,
                                      date: new Date(),
                                      position: {
                                        id: pos[i].id,
                                        name: pos[i].name,
                                      },
                                      user: {
                                        id: hiker.idUser,
                                        name: hiker.name + ' ' + hiker.surname,
                                        photo: hiker.photo['50'],
                                      },
                                    };
                                  }),
                                ),
                              );
                              success('Утверждено');
                            } catch (e) {
                              error(e);
                            }
                          }
                        }}
                      >
                        {approve ? 'Отменить утверждение' : 'Утвердить'}
                      </PohButton>
                    ) : null}
                  </div>
                ),
              };
            })}
        />
      </PohContainer>
    </div>
  );
};

export default FirstAidKitPage;
