/* eslint-disable @typescript-eslint/ban-ts-comment */
import React, { FormEvent } from 'react';

import { addMedicamentModalAsync } from '@apps/Medicaments/components/MedicamentModal/modalHelper';
import { getInputDate } from '@helpers/dateHelper';
import PohAlert from '@ui-kit/Alert';
import PohButton, { ButtonSize } from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohLoader from '@ui-kit/Loader';

import {
  IFirstAidKitSelectedForAdd,
  IFirstAidKitSMedicament,
} from '../../../Medicaments/@types/firstAidKit.types';
import { IMedicament } from '../../../Medicaments/@types/medicaments.types';
import {
  addMedicamentAsync,
  getMedicamentsAsync,
} from '../../../Medicaments/services/medicaments.services';
import HikerSelectInput from '../../@components/HikerSelectInput';
import { mapHikerToUser, mapUserToHiker } from '../../@mappers/hiking.mapper';
import { IHiker } from '../../@types/hiking.types';

interface IMedicamentSelectModalProps {
  id_hiking?: number;
  onAdd?: (selected: IFirstAidKitSelectedForAdd) => void;
  onEdit?: (selected: IFirstAidKitSMedicament) => void;
  onCancel: () => void;
  data?: IFirstAidKitSMedicament;
}

const MedicamentSelectModal: React.FC<IMedicamentSelectModalProps> = ({
  data,
  onAdd,
  onEdit,
  id_hiking,
}) => {
  const [isLoading, setIsLoading] = React.useState(false);
  const [err, setErr] = React.useState<string>('');
  const [medicaments, setMedicaments] = React.useState<IMedicament[]>([]);
  const [assignee, setAssignee] = React.useState<IHiker | null>(
    data?.assignee ? mapUserToHiker(data.assignee) : null,
  );

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);
        const m = await getMedicamentsAsync();
        setMedicaments(m);
      } catch (e) {
        setErr((e as Error).message);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, []);

  if (isLoading) {
    return <PohLoader />;
  }

  if (err.length) {
    return <PohAlert>{err}</PohAlert>;
  }

  const medicamentsInCategoriesMap: Record<string, IMedicament[]> = {};
  medicaments.map((m) => {
    const k = (m.category?.name ?? 'Без категории') as string;
    if (!medicamentsInCategoriesMap[k]) {
      medicamentsInCategoriesMap[k] = [];
    }
    medicamentsInCategoriesMap[k].push(m);
  });

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    const el = e.target as HTMLFormElement;

    // @ts-ignore
    const medId = +el.elements.medId.value;
    // @ts-ignore
    const comment = el.elements.comment.value;
    // @ts-ignore
    const deadline = new Date(el.elements.deadline.value);
    // @ts-ignore
    const amount = +(el.elements.amount.value ?? 0);
    // @ts-ignore
    const count_for_each = +el.elements.count_for_each.value;

    const medicament = medicaments.find((m) => m.id === medId);

    if (!medicament) {
      return;
    }

    data
      ? onEdit?.({
          ...data,
          comment,
          deadline,
          medicament,
          amount,
          count_for_each,
          assignee: assignee ? mapHikerToUser(assignee) : null,
        })
      : onAdd?.({
          comment,
          deadline,
          medicament,
          amount,
          count_for_each,
          assignee: assignee ? mapHikerToUser(assignee) : null,
        });
  };

  const handleAddMedicament = () => {
    addMedicamentModalAsync().then((m) => {
      addMedicamentAsync(m).then((newMedicament) => setMedicaments((ms) => [...ms, newMedicament]));
    });
  };

  return (
    <form onSubmit={handleSubmit}>
      <div className="mb-3">
        <label className="form-label d-flex align-items-end justify-content-between">
          Медикамент{' '}
          <PohButton size={ButtonSize.Small} onClick={handleAddMedicament}>
            +
          </PohButton>
        </label>
        <select
          className="form-control"
          name="medId"
          value={data?.medicament?.id}
          title={data?.medicament?.id.toString()}
        >
          {Object.entries(medicamentsInCategoriesMap).map(([k, v]) => {
            return (
              <optgroup label={k} key={k}>
                {v.map((medicament) => (
                  <option value={medicament.id} key={medicament.id}>
                    {medicament.name}
                  </option>
                ))}
              </optgroup>
            );
          })}
        </select>
      </div>
      <div className="mb-3">
        <label className="form-label">Количество</label>
        <input
          type={'number'}
          name="amount"
          min={0}
          defaultValue={data?.amount}
          className="form-control"
          required
        />
      </div>
      <div className="mb-3">
        <label className="form-label">Взять каждому</label>
        <input
          type={'number'}
          name="count_for_each"
          min={0}
          defaultValue={data?.count_for_each}
          className="form-control"
        />
      </div>
      <div className="mb-3">
        <label className="form-label">Комментарий</label>
        <textarea rows={3} name="comment" defaultValue={data?.comment} className="form-control" />
      </div>
      <div className="mb-3">
        <label className="form-label">Годен до</label>
        <input
          type={'date'}
          name="deadline"
          defaultValue={data?.deadline ? getInputDate(new Date(data.deadline), true) : undefined}
          min={getInputDate(new Date(), true)}
          className="form-control"
        />
      </div>
      {id_hiking && (
        <div className="mb-3">
          <label className="form-label">У кого</label>
          <div className="mb-2 d-flex align-items-center">
            <HikerSelectInput
              id_hiking={id_hiking}
              value={assignee}
              onChange={(hiker) => setAssignee(hiker)}
              placeholder="Не заполнять если у медика"
              wrapperClassName="flex-grow-1"
            />
            {assignee && <PohButton icon={IconsEnum.close} onClick={() => setAssignee(null)} />}
          </div>
        </div>
      )}
      <footer className="text-end">
        <button type="submit" className="btn btn-primary mt-3 ms-auto">
          {data ? 'Сохранить' : 'Добавить'}
        </button>
      </footer>
    </form>
  );
};

export default MedicamentSelectModal;
