import React from 'react';

import { showModal } from '@ui-kit/Modal';

import MedicamentSelectModal from './index';
import {
  IFirstAidKitSelectedForAdd,
  IFirstAidKitSMedicament,
} from '../../../Medicaments/@types/firstAidKit.types';

export function addFirstAidKitMedicamentModalAsync(
  id_hiking?: number,
): Promise<IFirstAidKitSelectedForAdd> {
  return new Promise((resolve) => {
    showModal({
      title: 'Добавление элемента в аптечку',
      children: (closeHandler: () => void) => (
        <MedicamentSelectModal
          id_hiking={id_hiking}
          onAdd={(bp) => {
            resolve(bp);
            closeHandler();
          }}
          onCancel={closeHandler}
        />
      ),
    });
  });
}

export function editFirstAidKitMedicamentModalAsync(
  m?: IFirstAidKitSMedicament,
  id_hiking?: number,
): Promise<IFirstAidKitSMedicament> {
  return new Promise((resolve) => {
    showModal({
      title: 'Редактирование элемента аптечки',
      children: (closeHandler: () => void) => (
        <MedicamentSelectModal
          id_hiking={id_hiking}
          data={m}
          onEdit={(bp) => {
            resolve(bp);
            closeHandler();
          }}
          onCancel={closeHandler}
        />
      ),
    });
  });
}
